  Ltac kB_tac := first [ kentry_tac | eapply kra_ok; evs; reflexivity ].
  Ltac knowB_tac :=
    lazymatch goal with
    | |- know_ok _ _ _ _ => unfold know_ok; knowB_tac
    | |- Forall _ [] => constructor
    | |- Forall _ (_ :: _) => constructor; [kB_tac | knowB_tac]
    end.

  Definition srB : list expr :=
    srs sr_id [(10%bv, EVar 32); (11%bv, EVar 33); (12%bv, EVar 34); (13%bv, ELit SHBASE); (14%bv, EVar 35); (15%bv, EVar 36);
               (2%bv, EVar 37); (1%bv, EVar 38)].
  Definition SCR_B_b0 := SCR [true] [EVar 40; EVar 41; EVar 42] [].
  Definition SCR_B_q0 := SCR [false; true] [EVar 40; EVar 41; EVar 42] [].
  Definition SCR_B_m := SCR [false; false; true] [EVar 40; EVar 41; EVar 42] [].
  Definition SCR_B_p := SCR [false; false; false] [EVar 40; EVar 41; EVar 42] [].

  Definition atLoop (R R' : bvmap 5 word) (q bcx : Z) : Prop :=
    aonlyTS R R' /\ getr R' 10%bv = Z_to_bv 64 q /\ getr R' 12%bv = Z_to_bv 64 bcx /\ getr R' 13%bv = Z_to_bv 64 SHBASE
    /\ getr R' 14%bv = Z_to_bv 64 key /\ getr R' 15%bv = Z_to_bv 64 (hmod key bc) /\ getr R' 16%bv = sxw key
    /\ getr R' 2%bv = Z_to_bv 64 (sp0 - 16) /\ getr R' 1%bv = ret.
  Definition atRet (R R' : bvmap 5 word) (r : Z) : Prop :=
    aonlyTS R R' /\ getr R' 10%bv = Z_to_bv 64 r /\ getr R' 2%bv = Z_to_bv 64 sp0 /\ getr R' 1%bv = ret.

  Lemma blkB : forall R (pw b q0 : Z),
    getr R 10%bv = Z_to_bv 64 obj -> getr R 11%bv = Z_to_bv 64 pw -> getr R 12%bv = Z_to_bv 64 bc ->
    getr R 13%bv = Z_to_bv 64 SHBASE -> getr R 14%bv = Z_to_bv 64 key -> getr R 15%bv = Z_to_bv 64 (hmod key bc) ->
    getr R 2%bv = Z_to_bv 64 (sp0 - 16) -> getr R 1%bv = ret ->
    0 <= pw < 2 ^ 64 -> bc <> 0 ->
    cell8 ASEGS M1 (bl + 8 * hmod key bc) b -> 0 <= b -> b + 8 <= 2 ^ 47 -> (b <> 0 -> cell8 ASEGS M1 b q0) -> (b <> 0 -> gz M1 b 8) ->
    exists R',
      ((b = 0 \/ q0 = 0) /\ msteps ASEGS (st R BB_PC M1) (st R' RET1 M1) /\ atRet R R' 0)
      \/ (b <> 0 /\ q0 <> 0 /\ 2 <= pw /\ msteps ASEGS (st R BB_PC M1) (st R' LM_PC M1) /\ atLoop R R' q0 bc)
      \/ (b <> 0 /\ q0 <> 0 /\ pw < 2 /\ msteps ASEGS (st R BB_PC M1) (st R' LP_PC M1) /\ atLoop R R' q0 (bc - 1)).
Proof.
    intros R pw b q0 H10 H11 H12 H13 H14 H15 H2 H1 Hpw Hbc Hb Hb0 Hb1 Hbq Hbgz.
    pose proof bc_rngA as Hbcr.
    pose proof (u_hdr U1) as Hh1. destruct Hh1 as [Hblc Hbcc Hp1c Hszc Hmlfc Hdefc].
    pose proof (u_obj_lo U1) as Ho0. pose proof (u_obj_hi U1) as Ho1. pose proof (u_obj_al U1) as Hoal.
    pose proof (u_bl_lo U1 Hbc) as Hbl0. pose proof (u_bl_hi U1) as Hbl1. pose proof (u_bl_al U1) as Hblal.
    pose proof (proj1 Hkey0) as Hkr. pose proof (proj1 Hb) as Hbr.
    pose proof (Z.mod_pos_bound key bc ltac:(lia)) as Hidx.
    assert (Hhm : 0 <= hmod key bc < bc) by (unfold hmod; lia).
    assert (Hbal : b <> 0 -> b mod 8 = 0).
    { intros Hbnz. destruct (u_bkt U1 (hmod key bc) Hhm) as (b' & Hb' & Hbok).
      assert (Hbb : b' = b) by exact (cell8_detA _ _ _ _ Hb' Hb). subst b'.
      destruct Hbok as [Hz | [Hin | (Hbs & _ & _)]]; [lia | |].
      - destruct (in_split_entsA V b ents Hin) as (l1 & k & v & l2 & He).
        assert (Hin2 : In (b, (k, v)) ents) by (rewrite He; apply in_or_app; right; left; reflexivity).
        destruct (u_node U1 b k v Hin2) as (_ & _ & _ & Hal & _). apply align16_8. exact Hal.
      - subst b. apply align_obj16A. exact Hoal. }
    pose proof (gz1 _ _ Hz_obj0 ltac:(lia) ltac:(lia)) as Gobj.
    pose proof (gz1 _ _ (Hz_bl0 Hbc) ltac:(lia) ltac:(lia)) as Gbl.
    Ltac seedB R pw b q0 :=
      let E := fresh "E" in let HR := fresh "HR" in
      pose (E := Eseed R [Z_to_bv 64 obj; Z_to_bv 64 pw; Z_to_bv 64 bc; Z_to_bv 64 key; Z_to_bv 64 (hmod key bc);
                          Z_to_bv 64 (sp0 - 16); ret; Z_to_bv 64 0; Z_to_bv 64 bl; Z_to_bv 64 b; Z_to_bv 64 q0]);
      assert (HR : regs_ok E srB R) by
        (apply regs_ok_srs; [apply regs_ok_seed|];
         repeat (apply Forall_cons; [cbn [fst snd]; split; [intros X; discriminate X | evs; first [assumption | match goal with H : getr R 13%bv = _ |- _ => rewrite H; reflexivity end]] |]); apply Forall_nil).
    Ltac ubB bl b hm Hbal :=
      first [ eapply (sc_trap_wrap _ _ _ _ _ bl (8 * hm)); [evs; rewrite ?w_mul, ?w_add by lia; f_equal; lia | evs; reflexivity | lia | lia | lia]
            | eapply (sc_trap_nullxor _ _ _ _ _ bl (8 * hm)); [evs; reflexivity | evs; rewrite ?w_mul, ?w_add by lia; f_equal; lia | lia | lia | lia]
            | eapply (sc_trap_null _ _ _ _ bl); [evs; reflexivity | lia]
            | eapply (sc_trap_align _ _ _ _ (8 * hm + bl)); [evs; rewrite ?w_mul, ?w_add by lia; reflexivity | lia | apply align8_add; apply align16_8; assumption]
            | eapply (sc_trap_align _ _ _ _ b); [evs; reflexivity | lia | apply Hbal; lia]
            | eapply (sc_read_cellw _ _ _ _ (bl + 8 * hm) 8%N b); [eassumption | lia | evs; rewrite ?w_mul, ?w_add, ?v_addi_Z by lia; f_equal; lia | evs; reflexivity]
            | eapply (sc_flat _ _ _ _ (8 * hm + bl)); [evs; rewrite ?w_mul, ?w_add by lia; reflexivity | lia | cbn [a_off]; lia | lia | cbn [a_off]; lia]
            | cbn [sc_denot]; evs; rewrite br_geu by lia; bool_lia ].
    Ltac runB R pw b q0 Hbal scr :=
      seedB R pw b q0;
      match goal with HR : regs_ok ?E srB R |- _ =>
        let HK := fresh "HK" in
        assert (HK : know_ok ASEGS E M1 (KNBx BB_PC srB scr)) by (kn_eval; knowB_tac);
        xrun HR HK 100%nat STOPS scr 50%N;
        [ split_scs; try sc_auto1; try sc_shdj; try ubB bl b (hmod key bc) Hbal
        | ] end.
    Ltac finLoopB :=
      match goal with HR' : regs_ok ?E' _ ?R', Hms : msteps _ _ (mkst _ _ _ _) |- _ =>
      let AO := fresh "AO" in
      assert (AO : aonlyTS _ R') by (eapply aonlyTS_of_syms; [exact HR'| vm_cast_no_check (@eq_refl bool true)]);
      let G10 := fresh "G" in rreg HR' 10%bv G10; let G12 := fresh "G" in rreg HR' 12%bv G12;
      let G13 := fresh "G" in rreg HR' 13%bv G13; let G14 := fresh "G" in rreg HR' 14%bv G14;
      let G15 := fresh "G" in rreg HR' 15%bv G15; let G16 := fresh "G" in rreg HR' 16%bv G16;
      let G2 := fresh "G" in rreg HR' 2%bv G2; let G1 := fresh "G" in rreg HR' 1%bv G1;
      split; [exact Hms|]; split; [exact AO|];
      split; [exact G10|]; split; [rewrite G12; first [reflexivity | apply w_addm; lia]|];
      split; [exact G13|]; split; [exact G14|]; split; [exact G15|];
      split; [rewrite G16; apply sextw_val; lia|]; split; [exact G2|exact G1]
      end.
    Ltac finRetB r :=
      match goal with HR' : regs_ok ?E' _ ?R', Hms : msteps _ _ (mkst _ _ _ _) |- _ =>
      let AO := fresh "AO" in
      assert (AO : aonlyTS _ R') by (eapply aonlyTS_of_syms; [exact HR'| vm_cast_no_check (@eq_refl bool true)]);
      let G10 := fresh "G" in rreg HR' 10%bv G10; let G2 := fresh "G" in rreg HR' 2%bv G2;
      let G1 := fresh "G" in rreg HR' 1%bv G1;
      let G2' := fresh "G" in assert (G2' : getr R' 2%bv = Z_to_bv 64 sp0) by (rewrite G2; rewrite ?w_addm, ?w_add by lia; f_equal; lia);
      let G10' := fresh "G" in assert (G10' : getr R' 10%bv = Z_to_bv 64 r) by (rewrite G10; reflexivity);
      exact (conj Hms (conj AO (conj G10' (conj G2' G1))))
      end.
    destruct (Z.eq_dec b 0) as [Hbz|Hbnz].
    - subst b. runB R pw 0 q0 Hbal (SCR [false; false; false; false; true] [EVar 40; EVar 41; EVar 42] []).
      exists R'. left. split; [left; reflexivity|]. finRetB 0.
    - specialize (Hbq Hbnz). specialize (Hbgz Hbnz). pose proof (proj1 Hbq) as Hqr.
      destruct (Z.eq_dec q0 0) as [Hqz|Hqnz].
      + subst q0. runB R pw b 0 Hbal (SCR [false; false; false; false; false; false; true] [EVar 40; EVar 41; EVar 42] []).
        exists R'. left. split; [right; reflexivity|]. finRetB 0.
      + destruct (Z.le_gt_cases 2 pw) as [Hw|Hw].
        * runB R pw b q0 Hbal (SCR [false; false; false; false; false; false; false; true] [EVar 40; EVar 41; EVar 42] []).
          exists R'. right; left. split; [exact Hbnz|]. split; [exact Hqnz|]. split; [exact Hw|]. finLoopB.
        * runB R pw b q0 Hbal (SCR [false; false; false; false; false; false; false; false] [EVar 40; EVar 41; EVar 42] []).
          exists R'. right; right. split; [exact Hbnz|]. split; [exact Hqnz|]. split; [lia|]. finLoopB.
Qed.

  Definition srL : list expr :=
