    let AO := fresh "AO" in
    assert (AO : aonlyTS _ R') by (eapply aonlyTS_of_syms; [exact HR'| vm_cast_no_check (@eq_refl bool true)]);
    let G10 := fresh "G" in rreg HR' 10%bv G10; let G2 := fresh "G" in rreg HR' 2%bv G2;
    let G1 := fresh "G" in rreg HR' 1%bv G1;
    let G2' := fresh "G" in assert (G2' : getr R' 2%bv = Z_to_bv 64 sp0) by (rewrite G2; rewrite ?w_addm, ?w_add by lia; f_equal; lia);
    let G10' := fresh "G" in assert (G10' : getr R' 10%bv = Z_to_bv 64 r) by (rewrite G10; reflexivity);
    exact (conj Hms (conj AO (conj G10' (conj G2' G1))))
    end.

  Lemma loopM : forall l2 l1 p k v R,
    ents = l1 ++ (p, (k, v)) :: l2 -> bc <> 0 ->
    getr R 10%bv = Z_to_bv 64 p -> getr R 12%bv = Z_to_bv 64 bc -> getr R 13%bv = Z_to_bv 64 SHBASE ->
    getr R 14%bv = Z_to_bv 64 key -> getr R 15%bv = Z_to_bv 64 (hmod key bc) -> getr R 16%bv = sxw key ->
    getr R 2%bv = Z_to_bv 64 (sp0 - 16) -> getr R 1%bv = ret ->
    exists R' r, found r /\
      ((msteps ASEGS (st R LM_PC M1) (st R' RET1 M1) /\ atRet R R' r) \/ (msteps ASEGS (st R LM_PC M1) (st R' RET2 M1) /\ atRet R R' r)).
Proof.
    induction l2 as [|[p' [k' v']] l2' IH]; intros l1 p k v R He Hbc H10 H12 H13 H14 H15 H16 H2 H1;
      pose proof bc_rngA as Hbcr;
      destruct (node_factsA l1 p k v _ He) as (Hp0 & Hp1 & Hk8 & Hk4 & Hkr & Hnx & Hgzp); cbn [hdaddr] in Hnx;
      assert (Hpal : p mod 16 = 0) by (destruct (u_node U1 p k v ltac:(rewrite He; apply in_or_app; right; left; reflexivity)) as (_ & _ & _ & Hal & _); exact Hal);
      pose proof (proj1 Hkey0) as Hkr0;
      assert (Hhm : 0 <= hmod key bc < bc) by (unfold hmod; apply Z.mod_pos_bound; lia);
      pose proof (Z.mod_pos_bound k bc ltac:(lia)) as Hmk';
      pose proof (Z.mod_pos_bound k 2 ltac:(lia)) as Hm2.
    Ltac finStepM :=
      match goal with HR' : regs_ok ?E' _ ?R', Hms : msteps _ _ (mkst _ _ _ _) |- _ =>
      let AO := fresh "AO" in
      assert (AO : aonlyTS _ R') by (eapply aonlyTS_of_syms; [exact HR'| vm_cast_no_check (@eq_refl bool true)]);
      let G10 := fresh "G" in rreg HR' 10%bv G10; let G12 := fresh "G" in rreg HR' 12%bv G12;
      let G13 := fresh "G" in rreg HR' 13%bv G13; let G14 := fresh "G" in rreg HR' 14%bv G14;
      let G15 := fresh "G" in rreg HR' 15%bv G15; let G16 := fresh "G" in rreg HR' 16%bv G16;
      let G2 := fresh "G" in rreg HR' 2%bv G2; let G1 := fresh "G" in rreg HR' 1%bv G1;
      exact (conj Hms (conj AO (conj G10 (conj G12 (conj G13 (conj G14 (conj G15 (conj G16 (conj G2 G1)))))))))
      end.
    - destruct (Z.eq_dec k key) as [Hkk|Hne].
      + subst k. runL R [Z_to_bv 64 p; Z_to_bv 64 bc; Z_to_bv 64 key; Z_to_bv 64 (hmod key bc); sxw key; Z_to_bv 64 (sp0 - 16); ret; Z_to_bv 64 0; Z_to_bv 64 key; sxw key] (SCR [false; false; false] [EVar 40; EVar 41; EVar 42] []) LM_PC; try (eapply (sc_trap_align _ _ _ _ p); [evs; reflexivity | lia | apply align16_8; exact Hpal]).
        exists R', p. split; [right; exists v; rewrite He; apply in_or_app; right; left; reflexivity|]. left. finL_ret p.
      + destruct (Z.eq_dec (k mod bc) (hmod key bc)) as [Hc|Hc].
        * destruct (Z.ltb_spec k bc) as [Hlt|Hge].
          -- rewrite (Z.mod_small k bc) in Hc by lia. runL R [Z_to_bv 64 p; Z_to_bv 64 bc; Z_to_bv 64 key; Z_to_bv 64 (hmod key bc); sxw key; Z_to_bv 64 (sp0 - 16); ret; Z_to_bv 64 0; Z_to_bv 64 k; Z_to_bv 64 0] (SCR [false; true; true; false; false] [EVar 40; EVar 41; EVar 42] []) LM_PC; try (eapply (sc_trap_align _ _ _ _ p); [evs; reflexivity | lia | apply align16_8; exact Hpal]). exists R', 0. split; [left; reflexivity|]. left. finL_ret 0.
          -- runL R [Z_to_bv 64 p; Z_to_bv 64 bc; Z_to_bv 64 key; Z_to_bv 64 (hmod key bc); sxw key; Z_to_bv 64 (sp0 - 16); ret; Z_to_bv 64 0; Z_to_bv 64 k; Z_to_bv 64 0] (SCR [false; true; false; false; false] [EVar 40; EVar 41; EVar 42] []) LM_PC; try (eapply (sc_trap_align _ _ _ _ p); [evs; reflexivity | lia | apply align16_8; exact Hpal]). exists R', 0. split; [left; reflexivity|]. left. finL_ret 0.
        * destruct (Z.ltb_spec k bc) as [Hlt|Hge].
          -- rewrite (Z.mod_small k bc) in Hc by lia. runL R [Z_to_bv 64 p; Z_to_bv 64 bc; Z_to_bv 64 key; Z_to_bv 64 (hmod key bc); sxw key; Z_to_bv 64 (sp0 - 16); ret; Z_to_bv 64 0; Z_to_bv 64 k; Z_to_bv 64 0] (SCR [false; true; true; true] [EVar 40; EVar 41; EVar 42] []) LM_PC; try (eapply (sc_trap_align _ _ _ _ p); [evs; reflexivity | lia | apply align16_8; exact Hpal]). exists R', 0. split; [left; reflexivity|]. right. finL_ret 0.
          -- runL R [Z_to_bv 64 p; Z_to_bv 64 bc; Z_to_bv 64 key; Z_to_bv 64 (hmod key bc); sxw key; Z_to_bv 64 (sp0 - 16); ret; Z_to_bv 64 0; Z_to_bv 64 k; Z_to_bv 64 0] (SCR [false; true; false; true] [EVar 40; EVar 41; EVar 42] []) LM_PC; try (eapply (sc_trap_align _ _ _ _ p); [evs; reflexivity | lia | apply align16_8; exact Hpal]). exists R', 0. split; [left; reflexivity|]. right. finL_ret 0.
    - assert (He' : ents = (l1 ++ [(p, (k, v))]) ++ (p', (k', v')) :: l2') by (rewrite He, <- app_assoc; reflexivity).
      destruct (node_factsA _ p' k' v' _ He') as (Hp0' & Hp1' & _).
      destruct (Z.eq_dec k key) as [Hkk|Hne].
      + subst k. runL R [Z_to_bv 64 p; Z_to_bv 64 bc; Z_to_bv 64 key; Z_to_bv 64 (hmod key bc); sxw key; Z_to_bv 64 (sp0 - 16); ret; Z_to_bv 64 0; Z_to_bv 64 key; sxw key] (SCR [false; false; false] [EVar 40; EVar 41; EVar 42] []) LM_PC; try (eapply (sc_trap_align _ _ _ _ p); [evs; reflexivity | lia | apply align16_8; exact Hpal]).
