  Lemma loopP : forall l2 l1 p k v R,
    ents = l1 ++ (p, (k, v)) :: l2 -> bc = 2 ->
    getr R 10%bv = Z_to_bv 64 p -> getr R 12%bv = Z_to_bv 64 (bc - 1) -> getr R 13%bv = Z_to_bv 64 SHBASE ->
    getr R 14%bv = Z_to_bv 64 key -> getr R 15%bv = Z_to_bv 64 (hmod key bc) -> getr R 16%bv = sxw key ->
    getr R 2%bv = Z_to_bv 64 (sp0 - 16) -> getr R 1%bv = ret ->
    exists R' r, found r /\
      ((msteps ASEGS (st R LP_PC M1) (st R' RET1 M1) /\ atRet R R' r) \/ (msteps ASEGS (st R LP_PC M1) (st R' RET2 M1) /\ atRet R R' r)).
Proof.
    induction l2 as [|[p' [k' v']] l2' IH]; intros l1 p k v R He Hbc2 H10 H12 H13 H14 H15 H16 H2 H1;
      pose proof bc_rngA as Hbcr;
      destruct (node_factsA l1 p k v _ He) as (Hp0 & Hp1 & Hk8 & Hk4 & Hkr & Hnx & Hgzp); cbn [hdaddr] in Hnx;
      assert (Hpal : p mod 16 = 0) by (destruct (u_node U1 p k v ltac:(rewrite He; apply in_or_app; right; left; reflexivity)) as (_ & _ & _ & Hal & _); exact Hal);
      pose proof (proj1 Hkey0) as Hkr0;
      assert (Hhm : 0 <= hmod key bc < bc) by (unfold hmod; apply Z.mod_pos_bound; lia);
      pose proof (Z.mod_pos_bound k bc ltac:(lia)) as Hmk';
      pose proof (Z.mod_pos_bound k 2 ltac:(lia)) as Hm2.
    Ltac finStepP :=
      match goal with HR' : regs_ok ?E' _ ?R', Hms : msteps _ _ (mkst _ _ _ _) |- _ =>
      let AO := fresh "AO" in
      assert (AO : aonlyTS _ R') by (eapply aonlyTS_of_syms; [exact HR'| vm_cast_no_check (@eq_refl bool true)]);
      let G10 := fresh "G" in rreg HR' 10%bv G10; let G12 := fresh "G" in rreg HR' 12%bv G12;
      let G13 := fresh "G" in rreg HR' 13%bv G13; let G14 := fresh "G" in rreg HR' 14%bv G14;
      let G15 := fresh "G" in rreg HR' 15%bv G15; let G16 := fresh "G" in rreg HR' 16%bv G16;
      let G2 := fresh "G" in rreg HR' 2%bv G2; let G1 := fresh "G" in rreg HR' 1%bv G1;
      exact (conj Hms (conj AO (conj G10 (conj G12 (conj G13 (conj G14 (conj G15 (conj G16 (conj G2 G1)))))))))
      end.
    - destruct (Z.eq_dec k key) as [Hkk|Hne].
      + subst k. runL R [Z_to_bv 64 p; Z_to_bv 64 (bc - 1); Z_to_bv 64 key; Z_to_bv 64 (hmod key bc); sxw key; Z_to_bv 64 (sp0 - 16); ret; Z_to_bv 64 0; Z_to_bv 64 key; sxw key] (SCR [false; false; false] [EVar 40; EVar 41; EVar 42] []) LP_PC; try (eapply (sc_trap_align _ _ _ _ p); [evs; reflexivity | lia | apply align16_8; exact Hpal]); try (cbn [sc_denot]; evs; rewrite w_and by lia; replace (bc - 1) with 1 by lia; rewrite land_1A; rewrite ?br_ne by lia; bool_lia).
        exists R', p. split; [right; exists v; rewrite He; apply in_or_app; right; left; reflexivity|]. left. finL_ret p.
      + destruct (Z.eq_dec (k mod 2) (hmod key bc)) as [Hc|Hc].
        * runL R [Z_to_bv 64 p; Z_to_bv 64 (bc - 1); Z_to_bv 64 key; Z_to_bv 64 (hmod key bc); sxw key; Z_to_bv 64 (sp0 - 16); ret; Z_to_bv 64 0; Z_to_bv 64 k; Z_to_bv 64 0] (SCR [false; true; false; false] [EVar 40; EVar 41; EVar 42] []) LP_PC; try (eapply (sc_trap_align _ _ _ _ p); [evs; reflexivity | lia | apply align16_8; exact Hpal]); try (cbn [sc_denot]; evs; rewrite w_and by lia; replace (bc - 1) with 1 by lia; rewrite land_1A; rewrite ?br_ne by lia; bool_lia). exists R', 0. split; [left; reflexivity|]. left. finL_ret 0.
        * runL R [Z_to_bv 64 p; Z_to_bv 64 (bc - 1); Z_to_bv 64 key; Z_to_bv 64 (hmod key bc); sxw key; Z_to_bv 64 (sp0 - 16); ret; Z_to_bv 64 0; Z_to_bv 64 k; Z_to_bv 64 0] (SCR [false; true; true] [EVar 40; EVar 41; EVar 42] []) LP_PC; try (eapply (sc_trap_align _ _ _ _ p); [evs; reflexivity | lia | apply align16_8; exact Hpal]); try (cbn [sc_denot]; evs; rewrite w_and by lia; replace (bc - 1) with 1 by lia; rewrite land_1A; rewrite ?br_ne by lia; bool_lia). exists R', 0. split; [left; reflexivity|]. right. finL_ret 0.
    - assert (He' : ents = (l1 ++ [(p, (k, v))]) ++ (p', (k', v')) :: l2') by (rewrite He, <- app_assoc; reflexivity).
      destruct (node_factsA _ p' k' v' _ He') as (Hp0' & Hp1' & _).
      destruct (Z.eq_dec k key) as [Hkk|Hne].
      + subst k. runL R [Z_to_bv 64 p; Z_to_bv 64 (bc - 1); Z_to_bv 64 key; Z_to_bv 64 (hmod key bc); sxw key; Z_to_bv 64 (sp0 - 16); ret; Z_to_bv 64 0; Z_to_bv 64 key; sxw key] (SCR [false; false; false] [EVar 40; EVar 41; EVar 42] []) LP_PC; try (eapply (sc_trap_align _ _ _ _ p); [evs; reflexivity | lia | apply align16_8; exact Hpal]); try (cbn [sc_denot]; evs; rewrite w_and by lia; replace (bc - 1) with 1 by lia; rewrite land_1A; rewrite ?br_ne by lia; bool_lia).
        exists R', p. split; [right; exists v; rewrite He; apply in_or_app; right; left; reflexivity|]. left. finL_ret p.
      + destruct (Z.eq_dec (k mod 2) (hmod key bc)) as [Hc|Hc].
        * assert (STEP : exists R1, msteps ASEGS (st R LP_PC M1) (st R1 LP_PC M1) /\ aonlyTS R R1
              /\ getr R1 10%bv = Z_to_bv 64 p' /\ getr R1 12%bv = Z_to_bv 64 (bc - 1) /\ getr R1 13%bv = Z_to_bv 64 SHBASE
              /\ getr R1 14%bv = Z_to_bv 64 key /\ getr R1 15%bv = Z_to_bv 64 (hmod key bc) /\ getr R1 16%bv = sxw key
              /\ getr R1 2%bv = Z_to_bv 64 (sp0 - 16) /\ getr R1 1%bv = ret).
          { runL R [Z_to_bv 64 p; Z_to_bv 64 (bc - 1); Z_to_bv 64 key; Z_to_bv 64 (hmod key bc); sxw key; Z_to_bv 64 (sp0 - 16); ret; Z_to_bv 64 0; Z_to_bv 64 k; Z_to_bv 64 p'] (SCR [false; true; false; true] [EVar 40; EVar 41; EVar 42] []) LP_PC; try (eapply (sc_trap_align _ _ _ _ p); [evs; reflexivity | lia | apply align16_8; exact Hpal]); try (cbn [sc_denot]; evs; rewrite w_and by lia; replace (bc - 1) with 1 by lia; rewrite land_1A; rewrite ?br_ne by lia; bool_lia). exists R'. finStepP. }
          destruct STEP as (R1 & Hms1 & A1 & G10 & G12 & G13 & G14 & G15 & G16 & G2 & G1).
          destruct (IH (l1 ++ [(p, (k, v))]) p' k' v' R1 He' Hbc2 G10 G12 G13 G14 G15 G16 G2 G1) as (R2 & r & Hf & Hr).
          exists R2, r. split; [exact Hf|].
          destruct Hr as [(Hms2 & A2 & F10 & F2 & F1) | (Hms2 & A2 & F10 & F2 & F1)]; [left|right];
            (split; [eapply msteps_trans; [exact Hms1 | exact Hms2]|]);
            exact (conj (fun x Hx => eq_trans (A2 x Hx) (A1 x Hx)) (conj F10 (conj F2 F1))).
        * runL R [Z_to_bv 64 p; Z_to_bv 64 (bc - 1); Z_to_bv 64 key; Z_to_bv 64 (hmod key bc); sxw key; Z_to_bv 64 (sp0 - 16); ret; Z_to_bv 64 0; Z_to_bv 64 k; Z_to_bv 64 0] (SCR [false; true; true] [EVar 40; EVar 41; EVar 42] []) LP_PC; try (eapply (sc_trap_align _ _ _ _ p); [evs; reflexivity | lia | apply align16_8; exact Hpal]); try (cbn [sc_denot]; evs; rewrite w_and by lia; replace (bc - 1) with 1 by lia; rewrite land_1A; rewrite ?br_ne by lia; bool_lia). exists R', 0. split; [left; reflexivity|]. right. finL_ret 0.
Qed.

