Definition find_stmt_A {AC : AllocCeiling} (L : Layout) (MI : MallocIface ASEGS L) (NS : Z) (V : Type) (nval : mem -> Z -> V -> Prop) : Prop :=
  forall (fx : FPState) (A : AS MI) (R : bvmap 5 word) (M : mem) (obj bl bc keyp key sp k0 : Z) (ents : list (Z * (Z * V))) (ret : word),
    umapx MI NS nval A M obj bl bc ents -> 24 <= NS ->
    cell4 ASEGS M keyp key -> 0 < keyp -> keyp + 4 <= 2 ^ 47 ->

    (forall i, GOT_SH <= i < GOT_SH + 8 -> M (Z_to_bv 64 i) = None) -> cell8 ASEGS M SHCELL SHBASE ->
    gz M obj 40 -> (bc <> 0 -> gz M bl (8 * bc)) -> (forall p k v, In (p, (k, v)) ents -> gz M p NS) ->
    shk M keyp k0 -> (k0 = 0 \/ (0 < k0 < 8 /\ keyp mod 8 + 3 < k0)) ->

    sp mod 16 = 0 -> 2 ^ 45 <= sp - 16 -> sp <= 2 ^ 47 -> stack_room ASEGS M sp 16 ->
    apart (sp - 16) 16 obj 40 -> apart (sp - 16) 16 keyp 4 -> (bc <> 0 -> apart (sp - 16) 16 bl (8 * bc)) ->
    (forall p k v, In (p, (k, v)) ents -> apart (sp - 16) 16 p NS) ->
    getr R 10%bv = Z_to_bv 64 obj -> getr R 11%bv = Z_to_bv 64 keyp -> getr R 2%bv = Z_to_bv 64 sp ->
    getr R 1%bv = ret -> ret_ok ret ->
    exists R' (p : Z),
      msteps ASEGS (@mkst fx R (Z_to_bv 64 FIND) M (seg_rom ASEGS))
                   (@mkst fx R' ret (wbytes M (Z_to_bv 64 (sp - 8)) (word_to_le_bytes 8 ret)) (seg_rom ASEGS))
      /\ keeps_cs R R' /\ getr R' 10%bv = Z_to_bv 64 p /\ (p = 0 \/ exists v, In (p, (key, v)) ents).

Theorem find_spec_A {AC : AllocCeiling} : forall (L : Layout) (MI : MallocIface ASEGS L) (NS : Z) (V : Type) (nval : mem -> Z -> V -> Prop),
  (forall M M' p v, nval M p v -> agree_on M M' (p + 20) (NS - 20) -> 0 < p -> p + NS <= 2 ^ 47 -> nval M' p v) ->
  find_stmt_A L MI NS V nval.
Proof.
